python3 -c "
import requests
import json

# Use Wikipedia API to fetch edit history
url = 'https://en.wikipedia.org/w/api.php'
params = {
    'action': 'query',
    'format': 'json',
    'list': 'recentchanges',
    'rclimit': 50,
    'rcprop': 'timestamp,comment',
    'rcsearch': 'Principle of double effect',
    'rcnamespace': 0
}

try:
    response = requests.get(url, params=params)
    data = response.json()
    if 'query' in data and 'recentchanges' in data['query']:
        for rc in data['query']['recentchanges']:
            if 'comment' in rc and 'Aquinas' in rc['comment'].lower():
                print(f'Date: {rc[\"timestamp\"]}, Comment: {rc[\"comment\"]}')
    else:
        print('No recent changes found or API error')

except Exception as e:
    print(f'Error: {e}')
"
